function build(src, h) {
  const out = {};
  for (const [ch, rows] of Object.entries(src)) {
    const w = Math.max(...rows.map(r => r.length));
    out[ch] = { w, rows, h };
  }
  return out;
}
export const FONT = { glyphs: build(G, 9), cap: 7, line: 10, space: 1, fallback: '?' };
export const TINY = { glyphs: build(T, 5), cap: 5, line: 6, space: 1, fallback: '?' };

export function glyph(font, ch) {
  const g = font.glyphs;
  if (g[ch]) return g[ch];
  const a = ALIAS[ch];
  if (a && g[a]) return g[a];
  if (font === TINY) { const up = ch.toUpperCase(); if (g[up]) return g[up]; }
  return g[font.fallback];
}
